                        if(id==StringTypeId && !TextValid(body.Buffer)) { Damage(report); offset=-1; }
                        else { NativePut(data+offset,(uint)body.Buffer.Length,4); body.Buffer.CopyTo(new Span<byte>(data+offset+8,body.Buffer.Length)); }
                    }
