                if(f.Counted && (RegionCount(value,f)<0 || RegionCount(value,f)>f.ArrayBound)) { return false; }
                if(f.Map) { for(int i=1;i<n;i++) { if(RegionKeyOrder(value.Child(f,i-1),value.Child(f,i),f.Table.Fields[0])>=0) { return false; } } }
                for(int i=0;i<n;i++)
