                if (f.Kind == 15) { return value.Child(f,i).Tag(f) == 0; }
                if (f.GetWide != null) { return value.Wide(f,i) == f.DefaultWide; }
                if (f.GetBuffer != null) { return value.Buffer(f)[i] == 0; }
