                    if (f.Counted && (RegionCount(value, f) < 0 || RegionCount(value, f) > f.ArrayBound)) { return false; }
                    if (RegionRides(value, f) && (!ids.Add(f.Id) || !RegionCollectPayload(value, f, ref ids))) { return false; }
